/**
 * TypeScript types for the Book Cover Archive public REST API (frontend scope).
 * Generated by reading the Spring Boot source; see API_CONTRACT.md for endpoints, auth and gotchas.
 * Paths in JSDoc are relative to src/main/java/com/bookcover/archive/.
 *
 * Conventions: UUID / Instant / LocalDate are strings. Nullable fields are `T | null`
 * (Jackson includes nulls). Request fields marked `?` may be omitted.
 */

/** UUID string, e.g. "3f2c1b9e-...". */
export type UUID = string;
/** ISO-8601 UTC instant, e.g. "2026-11-04T09:12:31.244374Z" (fraction length varies). */
export type Instant = string;
/** ISO local date "YYYY-MM-DD". */
export type LocalDate = string;

// ───────────────────────────── Enums ─────────────────────────────

/** domain/user/UserRole.java */
export type UserRole = "PUBLISHER" | "AUTHOR" | "DESIGNER" | "MEMBER" | "ADMIN";
/** Roles accepted by signup (ADMIN → 400). */
export type SignupRole = Exclude<UserRole, "ADMIN">;
/** domain/user/UserTitle.java */
export type UserTitle = "MEMBER" | "CONTRIBUTOR";
/** domain/common/ContentStatus.java — public reads only return PUBLISHED. */
export type ContentStatus = "DRAFT" | "PUBLISHED" | "HIDDEN" | "DELETED";
/** domain/book/CoverType.java */
export type CoverType = "FRONT" | "BACK";
/** domain/book/CoverVariantType.java — never null in responses (null in DB → UNKNOWN). */
export type CoverVariantType = "UNKNOWN" | "INITIAL" | "RECOVER" | "SPECIAL" | "PRINTING" | "IMAGE_REPLACEMENT";
/** domain/book/RibbonStatus.java — never null in responses. */
export type RibbonStatus = "UNKNOWN" | "CLEAN" | "BANDED";
/** domain/book/CoverLayout.java */
export type CoverLayout = "CENTER" | "LEFT" | "RIGHT" | "FULL_BLEED" | "MINIMAL";
/** domain/book/ImageSource.java */
export type ImageSource = "SCAN" | "PHOTO" | "LINK" | "OTHER";
/** domain/book/CreditRole.java */
export type CreditRole = "DESIGN" | "ART_DIRECTION" | "ILLUSTRATION" | "PHOTOGRAPHY" | "LETTERING";
/** domain/tag/TagCategory.java */
export type TagCategory = "STYLE" | "COLOR" | "LAYOUT" | "TYPOGRAPHY" | "ILLUSTRATION";
/** search/document/DocumentType.java */
export type DocumentType = "ORIGINAL" | "TRANSLATED" | "REDESIGN";
/** service/dto/SortOption.java — `sortBy` on GET /search. */
export type SortOption = "RELEVANCE" | "LIKES" | "NEWEST" | "YEAR_ASC" | "YEAR_DESC";
/** domain/social/LikeTargetType.java — targetId is a cover id (not a book id) or a redesign id. */
export type LikeTargetType = "ORIGINAL_COVER" | "TRANSLATED_COVER" | "REDESIGN";
/** domain/collection/CollectionItemType.java — itemId is a cover id or a redesign id. */
export type CollectionItemType = "ORIGINAL_COVER" | "TRANSLATED_COVER" | "REDESIGN";
/** domain/collection/CollectionVisibility.java — default PRIVATE. */
export type CollectionVisibility = "PRIVATE" | "PUBLIC" | "LINK_ONLY";

// ───────────────────────────── Common ─────────────────────────────

/** Sort descriptor inside Spring Data PageImpl JSON. */
export interface SpringSort {
  empty: boolean;
  sorted: boolean;
  unsorted: boolean;
}

/**
 * org.springframework.data.domain.PageImpl as serialized by Spring Boot 3.2 / Spring Data 3.2
 * (no PagedModel). Request with `page` (0-based), `size` (default 20, max 2000), `sort=prop,dir`.
 */
export interface SpringPage<T> {
  content: T[];
  pageable: {
    pageNumber: number;
    pageSize: number;
    sort: SpringSort;
    offset: number;
    paged: boolean;
    unpaged: boolean;
  };
  last: boolean;
  totalElements: number;
  totalPages: number;
  size: number;
  number: number;
  sort: SpringSort;
  first: boolean;
  numberOfElements: number;
  empty: boolean;
}

/** Standard Pageable query params. */
export interface PageParams {
  page?: number;
  size?: number;
  /** "property,asc" | "property,desc"; repeat for multiple. */
  sort?: string | string[];
}

/** Error codes actually emitted by the backend (others in ErrorCode.java are never used). */
export type EmittedErrorCode =
  | "VALIDATION_ERROR"
  | "MISSING_REQUIRED_FIELD"
  | "INVALID_IMAGE_SIZE"
  | "UNAUTHORIZED"
  | "FORBIDDEN"
  | "NOT_FOUND"
  | "DUPLICATE_ISBN"
  | "RATE_LIMITED"
  | "SEARCH_ERROR"
  | "INTERNAL_ERROR";

/** Every value declared in exception/ErrorCode.java (superset; most are unused). */
export type ErrorCode =
  | EmittedErrorCode
  | "INVALID_ISBN"
  | "INVALID_IMAGE"
  | "INVALID_IMAGE_RESOLUTION"
  | "INVALID_IMAGE_FORMAT"
  | "EMPTY_COMMENT"
  | "MISSING_FRONT_COVER"
  | "INVALID_TOKEN"
  | "EXPIRED_TOKEN"
  | "CONTENT_HIDDEN"
  | "USER_SUSPENDED"
  | "REPORT_RESTRICTED"
  | "BOOK_NOT_FOUND"
  | "USER_NOT_FOUND"
  | "COLLECTION_NOT_FOUND"
  | "COMMENT_NOT_FOUND"
  | "NO_SEARCH_RESULTS"
  | "DUPLICATE_EMAIL"
  | "DUPLICATE_ENTRY";

/**
 * exception/ErrorResponse.java. 401/403 produced by the security filter chain
 * (JwtAuthenticationEntryPoint / JwtAccessDeniedHandler) omit `details` entirely.
 */
export interface ErrorResponse {
  code: ErrorCode | string;
  message: string;
  details?: Record<string, unknown> | null;
  timestamp: Instant;
}

/** details of 404 NOT_FOUND (GlobalExceptionHandler.handleResourceNotFound). */
export interface NotFoundDetails {
  resourceType: string;
  fieldName: string;
  fieldValue: string | null;
}

/** details of 429 RATE_LIMITED; also sent as `Retry-After` header (seconds). */
export interface RateLimitDetails {
  retryAfter: number;
  limit: number;
}

/** details of 409 DUPLICATE_ISBN. */
export interface DuplicateIsbnDetails {
  existingBookId: UUID;
  isbn: string;
}

// ───────────────────────────── Auth ─────────────────────────────

/** controller/dto/auth/SignupRequest.java */
export interface SignupRequest {
  /** required, email format */
  email: string;
  /** required, 8–100 chars */
  password: string;
  /** required, 2–50 chars */
  displayName: string;
  /** required; ADMIN rejected (400) */
  role: SignupRole;
  /** http(s) URL; blank allowed */
  websiteUrl?: string | null;
  portfolioUrl?: string | null;
  snsAccounts?: Record<string, string> | null;
}

/** controller/dto/auth/LoginRequest.java */
export interface LoginRequest {
  email: string;
  password: string;
}

/** controller/dto/auth/TokenRefreshRequest.java — body of /auth/refresh and /auth/logout. */
export interface TokenRefreshRequest {
  refreshToken: string;
}

/** controller/dto/auth/AuthResponse.java (UserInfo) */
export interface AuthUserInfo {
  id: UUID;
  email: string;
  displayName: string;
  /** role.name() as plain string */
  role: UserRole;
}

/**
 * controller/dto/auth/AuthResponse.java — from signup (201), login, refresh.
 * Refresh tokens are single-use: always store the new pair.
 */
export interface AuthResponse {
  accessToken: string;
  refreshToken: string;
  tokenType: "Bearer";
  /** access-token lifetime in SECONDS (86400 by default); refresh lifetime (7 d) is not returned */
  expiresIn: number;
  user: AuthUserInfo;
}

