// ───────────────────────────── Search & browse ─────────────────────────────

/** Query params of GET /search (controller/SearchController.search). `query` must be non-blank or the result is empty. */
export interface SearchParams extends PageParams {
  query?: string;
  countryCode?: string;
  languageCode?: string;
  yearFrom?: number;
  yearTo?: number;
  genre?: string;
  publisherId?: UUID;
  tagIds?: UUID[];
  /** default RELEVANCE */
  sortBy?: SortOption;
}

/**
 * Search/browse document id: "original_<uuid>" | "translated_<uuid>" | "redesign_<uuid>".
 * Strip the prefix before calling /books/original/{uuid}, /books/translated/{uuid}, /redesigns/{uuid}.
 */
export type SearchDocumentId = `${"original" | "translated" | "redesign"}_${string}`;

/** service/dto/SearchResultItem.java */
export interface SearchResultItem {
  id: SearchDocumentId;
  type: DocumentType;
  title: string | null;
  /** representative (front) cover thumbnail; not hidden-aware */
  thumbnailUrl: string | null;
  author: string | null;
  /** null for redesigns */
  publisher: string | null;
  /** credited contributor names (all roles); null for redesigns */
  designers: string[] | null;
  year: number | null;
  countryCode: string | null;
  genre: string | null;
  likeCount: number | null;
  createdAt: Instant;
}

/** service/dto/SearchFacets.java — always empty maps (not implemented). */
export interface SearchFacets {
  countries: Record<string, number>;
  /** keys are year numbers serialized as strings */
  years: Record<string, number>;
  genres: Record<string, number>;
  tags: Record<string, number>;
}

/** service/dto/SearchResult.java (includes Jackson-serialized isEmpty() → `empty`). */
export interface SearchResult {
  items: SearchResultItem[];
  totalCount: number;
  facets: SearchFacets;
  /** 0-based */
  page: number;
  size: number;
  totalPages: number;
  empty: boolean;
}

/** service/dto/BrowseResultItem.java — same as SearchResultItem without `designers`. */
export interface BrowseResultItem {
  id: SearchDocumentId;
  type: DocumentType;
  title: string | null;
  thumbnailUrl: string | null;
  author: string | null;
  publisher: string | null;
  year: number | null;
  countryCode: string | null;
  genre: string | null;
  likeCount: number | null;
  createdAt: Instant;
}

/** service/dto/BrowseResult.java (includes `empty`). */
export interface BrowseResult {
  category: "latest" | "country" | "year" | "genre" | "tag";
  /** "all" for latest; otherwise the path value as string */
  categoryValue: string;
  totalCount: number;
  items: BrowseResultItem[];
  page: number;
  size: number;
  totalPages: number;
  empty: boolean;
}

/** Query params of GET /search/browse/latest (plain params, not Pageable; size 1–60). */
export interface BrowseLatestParams {
  /** default 0 */
  page?: number;
  /** default 24, max 60 */
  size?: number;
}

// ───────────────────────────── Tags / covers ─────────────────────────────

/** controller/dto/tag/TagResponse.java */
export interface TagResponse {
  id: UUID;
  name: string;
  category: TagCategory;
  usageCount: number;
  approved: boolean;
  createdAt: Instant;
}

/** controller/dto/book/BookCoverResponse.CreditResponse */
export interface CreditResponse {
  /** link to /designers/{designerId} */
  designerId: UUID;
  name: string;
  role: CreditRole;
}

/**
 * controller/dto/book/BookCoverResponse.java.
 * No "representative" flag: a cover is representative iff cover.id === book.frontCover.id.
 * When `hidden` is true, imageUrl/thumbnailUrl are null.
 */
export interface BookCoverResponse {
  id: UUID;
  imageUrl: string | null;
  /** 300×450 thumbnail */
  thumbnailUrl: string | null;
  originalFileName: string;
  /** may be null — fall back to the image's natural size, never stretch */
  width: number | null;
  height: number | null;
  fileSize: number | null;
  coverType: CoverType;
  imageSource: ImageSource | null;
  sourceUrl: string | null;
  sourceName: string | null;
  /** "#RRGGBB" */
  dominantColor: string | null;
  layout: CoverLayout | null;
  likeCount: number;
  commentCount: number;
  hidden: boolean;
  createdAt: Instant;
  /** e.g. "10쇄 리커버" */
  label: string | null;
  /** first printing that used this cover */
  printingFrom: number | null;
  usedFrom: LocalDate | null;
  /** null = inherit from the book */
  countryCode: string | null;
  /** null = inherit from the book */
  languageCode: string | null;
  credits: CreditResponse[];
  /** approved tags only */
  tags: TagResponse[];
  /** covers with the same value share a similar design across languages */
  similarGroupId: UUID | null;
  variantType: CoverVariantType;
  ribbonStatus: RibbonStatus;
  copyrightHolder: string | null;
}

